<section x-show="page==='projects'&&!projectId"><div class="page-heading"><div><div class="eyebrow">هر پروژه، یک مسیر تازه</div><h1>پروژه‌ها</h1><p>از یک هدف روشن شروع کنید؛ با هم به نتیجه برسید.</p></div><button class="button primary" @click="openProject()"><span x-html="$icon('Plus')"></span>پروژه جدید</button></div><div class="section-heading"><h2>همه پروژه‌ها <span class="count-badge" x-text="fa(projects.length)"></span></h2><span class="muted">نمای کلی فضای کار شما</span></div><div class="project-grid"><template x-for="p in projects" :key="p.id">@include('partials.project-card')</template><button class="new-project-card" @click="openProject()"><span class="new-project-plus" x-html="$icon('Plus')"></span><strong>یک هدف تازه در ذهن دارید؟</strong><span>پروژه جدید بسازید</span></button></div></section>
<template x-if="page==='projects'&&currentProject"><section><div class="page-heading"><div><button class="text-button back-link" @click="go('projects')"><span x-html="$icon('ArrowLeft')" class="rotate"></span>همه پروژه‌ها</button><h1 x-text="currentProject.name"></h1><p x-text="currentProject.description"></p></div><div class="button-row"><div class="avatar-stack"><template x-for="m in currentProject.members" :key="m.id"><span class="avatar small" :title="m.name" :style="`background:${color(m.id)}`" x-text="initials(m.name)"></span></template></div><button class="button" x-show="isOwner(currentProject)" @click="memberForm={email:'',role:'member'};showModal('member')"><span x-html="$icon('Users')"></span>افزودن عضو</button><button class="button primary" x-show="canWrite(currentProject)" @click="openTask()"><span x-html="$icon('Plus')"></span>افزودن تسک</button></div></div>
<div class="goal-card"><div class="goal-main"><div class="goal-kicker"><span x-html="$icon('Target')"></span>هدف اصلی پروژه<span class="status-badge">در یک راستا</span><button class="icon-btn" x-show="isOwner(currentProject)" @click="openGoal()" aria-label="ویرایش هدف" x-html="$icon('Pencil')"></button></div><h2 x-text="currentProject.goal?.title"></h2><p x-text="currentProject.goal?.description"></p><div class="success-criteria"><span x-html="$icon('CheckCircle2')"></span><span><strong>معیار موفقیت:</strong> <span x-text="currentProject.goal?.success_criteria"></span></span></div><div class="goal-dates"><span><span x-html="$icon('CalendarDays')"></span>شروع: <strong x-text="date(currentProject.goal?.start_date)"></strong></span><span>مقصد: <strong x-text="date(currentProject.goal?.end_date)"></strong></span></div></div><div class="goal-progress"><div class="progress-ring" :style="`--progress:${progress(currentProject)}%`"><strong x-text="fa(progress(currentProject))+'٪'"></strong></div><strong>در مسیر هدف</strong><small x-text="fa(tasks.filter(t=>t.project_id===projectId&&t.completed_at).length)+' از '+fa(tasks.filter(t=>t.project_id===projectId).length)+' تسک تکمیل شده'"></small></div></div>
<div class="section-heading stage-heading"><div><h2>مراحل محصول <span class="count-badge" x-text="fa(currentProject.stages.length)"></span></h2><p>مسیر رسیدن به هدف، قدم به قدم</p></div><div class="button-row"><select class="compact-select" x-model="taskFilter" aria-label="فیلتر تسک‌های پروژه"><option value="active">تسک‌های باز</option><option value="all">همه تسک‌ها</option><option value="done">تکمیل‌شده‌ها</option></select><button class="button" x-show="canWrite(currentProject)" @click="openStage()"><span x-html="$icon('Plus')"></span>مرحله جدید</button></div></div>
<div class="board product-board"><template x-for="(s,i) in currentProject.stages" :key="s.id"><section class="board-column" @dragover.prevent @drop.prevent="reorderStage(s)"><div class="stage-column-head" :draggable="canWrite(currentProject)" @dragstart="dragStage=s.id;$event.dataTransfer.effectAllowed='move'" @dragend="dragStage=null"><div><span class="stage-dot" :style="`background:${['#baa78e','#a899cf','#8db7aa','#8ba9c9','#daaa7b'][i%5]}`"></span><h3 x-text="s.title"></h3><span class="count-badge" x-text="fa(stageTotal(s.id))"></span></div><div x-data="{open:false}" class="stage-menu" @click.outside="open=false"><button class="icon-btn" @click="open=!open" :aria-label="'گزینه‌های '+s.title" x-html="$icon('MoreHorizontal')"></button><div class="dropdown-menu" x-show="open"><button @click="openStage(s);open=false" :disabled="!canWrite(currentProject)">ویرایش مرحله</button><button @click="moveStage(s,-1);open=false" :disabled="!canWrite(currentProject)">یک مرحله قبل</button><button @click="moveStage(s,1);open=false" :disabled="!canWrite(currentProject)">یک مرحله بعد</button><button class="danger-text" @click="deleteStage(s);open=false" :disabled="!canWrite(currentProject)">حذف مرحله</button></div></div></div><div class="stage-meta"><span x-text="date(s.start_date)+' — '+date(s.end_date)"></span><span x-text="fa(stageProgress(s.id))+'٪'"></span></div><div class="progress-track stage-track"><i :style="`width:${stageProgress(s.id)}%;background:${['#baa78e','#a899cf','#8db7aa','#8ba9c9','#daaa7b'][i%5]}`"></i></div><small class="stage-completed" x-text="fa(stageDone(s.id))+' از '+fa(stageTotal(s.id))+' تسک تکمیل شده'"></small><div class="column-tasks"><template x-for="t in stageTasks(s.id)" :key="t.id">@include('partials.task-card')</template><div class="column-empty" x-show="!stageTasks(s.id).length"><span x-html="$icon('CheckCheck')"></span><span>فعلاً تسکی در این نما نیست.</span></div></div><button class="add-column-task" x-show="canWrite(currentProject)" @click="openTask(null,s,currentProject)"><span x-html="$icon('Plus')"></span>افزودن تسک</button></section></template><button class="empty-state" x-show="!currentProject.stages.length&&canWrite(currentProject)" @click="openStage()">هنوز مرحله‌ای تعریف نشده است. + افزودن اولین مرحله</button></div>
<div class="section-heading team-heading"><div><h2>مسیر اعضای تیم</h2><p>مسیرهای متفاوت، به سوی یک هدف مشترک</p></div><span class="subtle-label"><span x-html="$icon('Users')"></span><span x-text="fa(currentProject.members.length)+' عضو تیم'"></span></span></div><div class="team-grid"><template x-for="m in currentProject.members" :key="m.id"><article class="team-card"><div class="team-card-head"><span class="avatar" :style="`background:${color(m.id)}`" x-text="initials(m.name)"></span><div><strong x-text="m.name"></strong><small x-text="({owner:'مدیر پروژه',member:'عضو تیم',viewer:'بیننده'})[m.pivot.role]"></small></div><button class="icon-btn" @click="openStage(null,m)" x-show="canWrite(currentProject)" :aria-label="'افزودن مرحله برای '+m.name" x-html="$icon('Plus')"></button></div><div class="team-stages"><template x-for="(s,i) in currentProject.member_stages.filter(s=>s.user_id===m.id)" :key="s.id"><div class="team-stage" :draggable="canWrite(currentProject)" @dragstart.stop="teamDrag=s.id" @dragover.prevent @drop.stop.prevent="reorderStage(s,'member',m)"><span class="step-number" x-text="fa(i+1)"></span><button @click="openStage(s,m)" x-text="s.title"></button><button class="icon-btn" x-show="canWrite(currentProject)" @click="moveStage(s,-1,'member',m)" aria-label="جابجایی به قبل" x-html="$icon('GripVertical')"></button></div></template><p class="muted" x-show="!currentProject.member_stages.some(s=>s.user_id===m.id)">مسیر این عضو هنوز تعریف نشده است.</p></div></article></template></div></section></template>
<div class="empty-state" x-show="page==='projects'&&projectId&&!currentProject&&!loading"><h2>پروژه در دسترس نیست</h2><button class="button" @click="go('projects')">بازگشت به پروژه‌ها</button></div>
